blocks.text:
semantic_models:
  - name: orders
    model: ref('fct_orders')
    defaults: {agg_time_dimension: order_date}
    entities:
      - {name: order, type: primary, expr: order_id}
      - {name: customer, type: foreign, expr: customer_id}
    dimensions:
      - name: order_date
        type: time
        type_params: {time_granularity: day}
      - {name: status, type: categorical}
    measures:
      - {name: order_amount, agg: sum, expr: amount}
      - {name: order_count, agg: sum, expr: 1}
      - {name: buyers, agg: count_distinct, expr: customer_id}

  - name: customers
    model: ref('dim_customers')
    entities:
      - {name: customer, type: primary, expr: customer_id}
    dimensions:
      - {name: region, type: categorical}
      - {name: segment, type: categorical}

metrics:
  - name: revenue
    type: simple
    type_params: {measure: order_amount}
    filter: "{{ Dimension('order__status') }} = 'paid'"
  - name: total_orders
    type: simple
    type_params: {measure: order_count}
  - name: average_order_value
    type: ratio
    type_params: {numerator: revenue, denominator: total_orders}
  - name: revenue_growth_mom
    type: derived
    type_params:
      expr: (revenue - revenue_prev) / revenue_prev
      metrics:
        - {name: revenue}
        - {name: revenue, offset_window: 1 month, alias: revenue_prev}
